import re
raw = [
    ("win", {"EventID": 4625, "TargetUserName": "kim", "IpAddress": "10.1.2.3"}),
    ("linux", "Nov 20 01:02:05 web01 sshd[811]: Failed password for kim from 10.1.2.3 port 52144 ssh2"),
]
def normalize(src, r):
    if src == "win" and r["EventID"] == 4625:
        return {"action": "logon_failed", "user": r["TargetUserName"], "src_ip": r["IpAddress"], "os": "windows"}
    m = re.search(r"Failed password for (\S+) from (\S+)", r)
    if m:
        return {"action": "logon_failed", "user": m[1], "src_ip": m[2], "os": "linux"}
for s, r in raw:
    print(normalize(s, r))
# {'action': 'logon_failed', 'user': 'kim', 'src_ip': '10.1.2.3', 'os': 'windows'}
# {'action': 'logon_failed', 'user': 'kim', 'src_ip': '10.1.2.3', 'os': 'linux'}

from datetime import datetime as dt, timedelta
ev = [("01:00:01", "fail"), ("01:00:09", "fail"), ("01:00:15", "fail"),
      ("01:00:22", "fail"), ("01:00:30", "fail"), ("01:01:40", "success")]
def t(s):
    return dt.strptime(s, "%H:%M:%S")
fails = [t(x) for x, k in ev if k == "fail"]
for x, k in ev:
    if k == "success":
        recent = [f for f in fails if timedelta(0) <= t(x) - f <= timedelta(minutes=10)]
        verdict = "경보(T1110 다음 T1078)" if len(recent) >= 5 else "통과"
        print(f"{x} 로그인 성공, 직전 10분 실패 {len(recent)}회 -> {verdict}")
# 01:01:40 로그인 성공, 직전 10분 실패 5회 -> 경보(T1110 다음 T1078)
